from typing import List


class Solution:
    """
    比特位计数 - 动态规划（最高有效位）

    bits[i] = bits[i - highBit] + 1
    highBit 是小于等于 i 的最大 2 的幂

    时间复杂度：O(n)
    空间复杂度：O(1)（不计输出空间）
    """

    def countBits(self, n: int) -> List[int]:
        bits = [0]
        highBit = 0
        for i in range(1, n + 1):
            # i & (i - 1) == 0 判断 i 是否是 2 的幂
            if i & (i - 1) == 0:
                highBit = i
            bits.append(bits[i - highBit] + 1)
        return bits


# 方法二：最低有效位
class Solution2:
    def countBits(self, n: int) -> List[int]:
        bits = [0] * (n + 1)
        for i in range(1, n + 1):
            bits[i] = bits[i & (i - 1)] + 1
        return bits


# 方法三：右移
class Solution3:
    def countBits(self, n: int) -> List[int]:
        bits = [0] * (n + 1)
        for i in range(1, n + 1):
            bits[i] = bits[i >> 1] + (i & 1)
        return bits
